('lib/content/gpx_scolarite/dps_dpg/crime_delit_contre_personne_pages/dignite_personne/traite_etres_humains_page.dart','f00040','II — Élément matériel',40,'_SubTitle','C) Une mise à disposition','C) Une mise à disposition','{"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/dps_dpg/crime_delit_contre_personne_pages/dignite_personne/traite_etres_humains_page.dart','f00041','II — Élément matériel',41,'_Paragraph','La victime doit être mise à la disposition de l’auteur ou d’un tiers (même non identifié). ','La victime doit être mise à la disposition de l’auteur ou d’un tiers (même non identifié). ','{}'::jsonb,true),
